		workGroupCode = "// This is an example of using goroutines and channels\n// to create an asynchrounous work group.\n// The work group queues several workers then only allows a specific number\n// of the workers to run at a time using a limited set of tokens.\npackage main\n\nimport (\n\t\"errors\"\n\t\"fmt\"\n\t\"math/rand\"\n\t\"sync\"\n)\n\nfunc newFibonacciWorker(n int) func() (int, error) {\n\treturn func() (int, error) {\n\t\tif n < 0 {\n\t\t\treturn 0, errors.New(`given iteration value, \"n\", must be zero or more`)\n\t\t}\n\t\tif n == 0 {\n\t\t\treturn 0, nil\n\t\t}\n\t\ta, b := 0, 1\n\t\tfor i := 2; i <= n; i++ {\n\t\t\ta, b = b, a+b\n\t\t}\n\t\treturn b, nil\n\t}\n}\n\ntype WorkGroup struct {\n\ttokenSet chan int\n\twait     *sync.WaitGroup\n}\n\nfunc NewWorkGroup(size int) *WorkGroup {\n\ttokenSet := make(chan int, size)\n\tfor i := 0; i < size; i++ {\n\t\ttokenSet <- i\n\t}\n\treturn &WorkGroup{\n\t\ttokenSet: tokenSet,\n\t\twait:     &sync.WaitGroup{},\n\t}\n}\n\nfunc AddWorker[T any](wg *WorkGroup, name string, worker func() (T, error)) {\n\twg.wait.Add(1)\n\tgo func() {\n\t\ttoken := <-wg.tokenSet\n\t\tdefer func() {\n\t\t\twg.tokenSet <- token\n\t\t\twg.wait.Done()\n\t\t}()\n\n\t\tfmt.Printf(\"[%d] %s started\\n\", token, name)\n\t\tresult, err := worker()\n\t\tif err != nil {\n\t\t\tfmt.Printf(\"[%d] %s failed: %v\\n\", token, name, err)\n\t\t\treturn\n\t\t}\n\t\tfmt.Printf(\"[%d] %s returned %v\\n\", token, name, result)\n\t}()\n}\n\nfunc main() {\n\twg := NewWorkGroup(10)\n\tfor i := 0; i < 100; i++ {\n\t\tn := rand.Intn(10) - 1\n\t\tname := fmt.Sprintf(`worker %d - fib(%d)`, i, n)\n\t\tAddWorker(wg, name, newFibonacciWorker(n))\n\t}\n\twg.wait.Wait()\n\tfmt.Println(`Done`)\n}\n";
		typerCode = "// This is an example of using sleep to slowly output text\n// to look as if someone was manually typing the text very fast.\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math/rand\"\n\t\"time\"\n)\n\nfunc main() {\n\tfor _, c := range ipsum {\n\t\tfmt.Print(string([]rune{c}))\n\n\t\tdur := time.Duration(rand.Intn(10)+2) * time.Millisecond\n\t\ttime.Sleep(dur)\n\t}\n}\n\nconst ipsum = `RE: We need an illustration of a paradigm shift for a great plan!\nLet me diarize this then we can synchronise ourselves at a later sprint.\nFirst-order optimal strategies should be put in the parking lot.\nMy supervisor didn't like the smell of the latest revision you gave me,\nso roll back to the prior revision as discussed in stand-up.\n\nManage expectations because the throughput is all exactly as we previously stated.\nRamp up the button-up approach then circle back for future adjustments until it is done done.\nThat's not on the roadmap. You need to touch base. Let's set up a meeting to discuss\nwhat the following meeting will be about. Reserve a whiteboard for a post-meeting\nretrospective meeting. This is that meeting!\n\nCan you champion this proceduralization for technologically savvy bandwidth?\nParallel paths inspire more creative, innovative, and energized philosophy to\nattract our stakeholders back to the drawing board to get buy-in.\nThis proposal is a win-win situation that will cause a stellar paradigm shift,\ndisrupt the charts, and move the needle.\n\nIf you don't understand, you need to re-read Monday's memo and please forward me\na copy so that I can be sure you got it.`\n";
		donutCode = "// This is a spinning donut (torus) rendered in the terminal\n// using Braille unicode characters as a rough dither.\npackage main\n\nimport (\n\t\"errors\"\n\t\"fmt\"\n\t\"math\"\n\t\"strings\"\n\t\"time\"\n)\n\nconst (\n\tscreenWidth  = 40\n\tscreenHeight = 20\n\tframes       = 1200\n)\n\nvar luminance = [9]rune{0x2800, 0x2801, 0x2881, 0x2891, 0x2895, 0x289D, 0x28DD, 0x28DF, 0x28FF}\n\nfunc main() {\n\tvar a, b float64\n\tscreen := newScreen(screenWidth, screenHeight)\n\tfor f := 0; f < frames; f++ {\n\t\tscreen.clear()\n\n\t\tsinA, cosA := math.Sin(a), math.Cos(a)\n\t\tsinB, cosB := math.Sin(b), math.Cos(b)\n\t\tfor jStep := 0; jStep < 90; jStep++ {\n\t\t\tj := float64(jStep) * 0.07\n\t\t\tsinJ, cosJ := math.Sin(j), math.Cos(j)\n\t\t\tfor iStep := 0; iStep < 314; iStep++ {\n\t\t\t\ti := float64(iStep) * 0.02\n\t\t\t\tsinI, cosI := math.Sin(i), math.Cos(i)\n\n\t\t\t\th := cosJ + 2\n\t\t\t\td := 1.0 / (sinI*h*sinA + sinJ*cosA + 5)\n\t\t\t\tt := sinI*h*cosA - sinJ*sinA\n\t\t\t\tx := d * (cosI*h*cosB - t*sinB)\n\t\t\t\ty := d * (cosI*h*sinB + t*cosB)\n\t\t\t\tc := ((sinJ*sinA-sinI*cosJ*cosA)*cosB - sinI*cosJ*sinA - sinJ*cosA - cosI*cosJ*sinB)\n\t\t\t\tc = c/math.Sqrt2*2.0 - 1.0\n\t\t\t\tscreen.write(x, y, c, d)\n\t\t\t}\n\t\t}\n\t\tscreen.render()\n\t\ta += 0.08\n\t\tb += 0.03\n\t\ttime.Sleep(50 * time.Millisecond)\n\t}\n}\n\ntype screen struct {\n\twidth  int\n\theight int\n\tz      [][]float64\n\tc      [][]rune\n}\n\nfunc newScreen(width, height int) *screen {\n\tif width < 1 || height < 1 {\n\t\tpanic(errors.New(`invalid screen size`))\n\t}\n\tz := make([][]float64, height)\n\tc := make([][]rune, height)\n\tfor y := range c {\n\t\tz[y] = make([]float64, width)\n\t\tc[y] = make([]rune, width)\n\t}\n\treturn &screen{\n\t\twidth:  width,\n\t\theight: height,\n\t\tz:      z,\n\t\tc:      c,\n\t}\n}\n\nfunc (s *screen) clear() {\n\tfor y := range s.z {\n\t\tzRow := s.z[y]\n\t\tcRow := s.c[y]\n\t\tfor x := range zRow {\n\t\t\tzRow[x] = 0.0\n\t\t\tcRow[x] = ' '\n\t\t}\n\t}\n}\n\nfunc quantize(v float64, max int) (int, bool) {\n\tq := int((v + 1.0) * 0.5 * float64(max))\n\toob := q < 0 || q >= max\n\treturn q, oob\n}\n\nfunc clamp(v, max int) int {\n\tif v < 0 {\n\t\treturn 0\n\t}\n\tif v > max {\n\t\treturn max\n\t}\n\treturn v\n}\n\nfunc (s *screen) write(x, y, c, depth float64) {\n\tix, oob := quantize(x, s.width)\n\tif oob {\n\t\treturn\n\t}\n\n\tiy, oob := quantize(y, s.height)\n\tif oob {\n\t\treturn\n\t}\n\n\tif depth <= s.z[iy][ix] {\n\t\treturn\n\t}\n\ts.z[iy][ix] = depth\n\n\tlux := len(luminance)\n\tic, oob := quantize(c, lux)\n\tif oob {\n\t\tic = clamp(ic, lux-1)\n\t}\n\ts.c[iy][ix] = luminance[ic]\n}\n\nfunc (t *screen) render() {\n\tvar sb strings.Builder\n\tsb.WriteByte('\\x0c') // clear playgound output\n\tfor _, cRow := range t.c {\n\t\tsb.WriteString(string(cRow))\n\t\tsb.WriteByte('\\n')\n\t}\n\tfmt.Print(sb.String())\n}\n";
